import { workflow, step, ref } from "@executioncontrolprotocol/core"

export default workflow("Email from notes")
  .id("email-from-notes")
  .accepts({ type: "object", properties: { notes: { type: "string" } }, required: ["notes"] })
  .returns({
    type: "object",
    properties: { email: { type: "object" }, actions: { type: "object" } },
    required: ["email", "actions"],
  })
  .run([
    step("@executioncontrolprotocol/ollama.generate", "Generate Email")
      .id("email")
      .with({
        prompt: "Generate a short sample email with a meeting summary from these notes:",
        context: ref("notes"),
      })
      .as("email"),
    step("@executioncontrolprotocol/ollama.generate", "Extract Action Items")
      .id("actions")
      .with({
        prompt: "Extract the key action items from the following email:",
        context: ref("email.text"),
      })
      .as("actions"),
  ])
